1	import "jsr:@supabase/functions-js/edge-runtime.d.ts";
2	import { createClient } from "jsr:@supabase/supabase-js@2";
3	
4	const corsHeaders = {
5	  "Access-Control-Allow-Origin": "*",
6	  "Access-Control-Allow-Headers":
7	    "authorization, x-client-info, apikey, content-type",
8	};
9	
10	Deno.serve(async (req) => {
11	  if (req.method === "OPTIONS") {
12	    return new Response("ok", { headers: corsHeaders });
13	  }
14	
15	  try {
16	    // ── Auth ──────────────────────────────────────────────────────────────────
17	    const authHeader = req.headers.get("Authorization");
18	    if (!authHeader) {
19	      return new Response(JSON.stringify({ error: "Unauthorized" }), {
20	        status: 401,
21	        headers: { ...corsHeaders, "Content-Type": "application/json" },
22	      });
23	    }
24	
25	    const supabase = createClient(
26	      Deno.env.get("SUPABASE_URL")!,
27	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
28	    );
29	
30	    const token = authHeader.replace("Bearer ", "");
31	    const {
32	      data: { user },
33	      error: authError,
34	    } = await supabase.auth.getUser(token);
35	
36	    if (authError || !user) {
37	      return new Response(JSON.stringify({ error: "Unauthorized" }), {
38	        status: 401,
39	        headers: { ...corsHeaders, "Content-Type": "application/json" },
40	      });
41	    }
42	
43	    // ── Validate input ────────────────────────────────────────────────────────
44	    const body = await req.json() as { resume_id?: string };
45	    const { resume_id } = body;
46	
47	    if (!resume_id || typeof resume_id !== "string") {
48	      return new Response(JSON.stringify({ error: "resume_id is required" }), {
49	        status: 400,
50	        headers: { ...corsHeaders, "Content-Type": "application/json" },
51	      });
52	    }
53	
54	    // ── Verify resume belongs to this user ────────────────────────────────────
55	    const { data: resume, error: resumeError } = await supabase
56	      .from("resumes")
57	      .select("id, job_id, jobs!inner(user_id)")
58	      .eq("id", resume_id)
59	      .single();
60	
61	    if (resumeError || !resume) {
62	      return new Response(JSON.stringify({ error: "Resume not found" }), {
63	        status: 404,
64	        headers: { ...corsHeaders, "Content-Type": "application/json" },
65	      });
66	    }
67	
68	    // Type assertion for the joined data
69	    const jobData = resume.jobs as unknown as { user_id: string };
70	    if (jobData.user_id !== user.id) {
71	      return new Response(JSON.stringify({ error: "Forbidden" }), {
72	        status: 403,
73	        headers: { ...corsHeaders, "Content-Type": "application/json" },
74	      });
75	    }
76	
77	    // ── Call RPC ──────────────────────────────────────────────────────────────
78	    const { data: duplicates, error: rpcError } = await supabase.rpc(
79	      "find_resume_duplicates",
80	      { p_resume_id: resume_id },
81	    );
82	
83	    if (rpcError) {
84	      console.error("find_resume_duplicates RPC error:", rpcError);
85	      throw new Error("Duplicate search failed");
86	    }
87	
88	    return new Response(
89	      JSON.stringify({ duplicates: duplicates ?? [] }),
90	      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
91	    );
92	  } catch (error: unknown) {
93	    const message = error instanceof Error ? error.message : "Unknown error";
94	    console.error("find-duplicates error:", message);
95	    return new Response(JSON.stringify({ error: message }), {
96	      status: 500,
97	      headers: { ...corsHeaders, "Content-Type": "application/json" },
98	    });
99	  }
100	});
