1	import { useQuery } from "@tanstack/react-query";
2	import { supabase } from "@/integrations/supabase/client";
3	
4	// ─── Types ────────────────────────────────────────────────────────────────────
5	
6	export interface DuplicateMatch {
7	  duplicate_resume_id: string;
8	  duplicate_job_id: string;
9	  duplicate_job_title: string;
10	  match_type: "email" | "phone" | "embedding";
11	  similarity: number;
12	}
13	
14	interface FindDuplicatesResponse {
15	  duplicates: DuplicateMatch[];
16	}
17	
18	// ─── Hook: useDuplicates ────────────────────────────────────────────────────
19	
20	/**
21	 * Finds duplicate resumes across jobs for a given resume.
22	 * Uses the find-duplicates edge function which calls the find_resume_duplicates RPC.
23	 * 10 min staleTime — duplicates don't change frequently.
24	 */
25	export function useDuplicates(resumeId: string | undefined) {
26	  return useQuery<DuplicateMatch[]>({
27	    queryKey: ["duplicates", resumeId],
28	    queryFn: async (): Promise<DuplicateMatch[]> => {
29	      if (!resumeId) return [];
30	
31	      const { data, error } = await supabase.functions.invoke<FindDuplicatesResponse>(
