4	
5	const ALLOWED_ORIGINS = [
6	  Deno.env.get("APP_URL") || "https://rankora.co",
7	  "https://www.rankora.co",
8	  "http://localhost:8080",
9	  "http://localhost:5173",
10	];
11	
12	function getCorsOrigin(req: Request): string {
13	  const origin = req.headers.get("origin") || "";
14	  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
15	}
16	
17	interface SendSmsRequest {
18	  resume_id: string;
19	  job_id: string;
20	  to_phone: string;
21	  message: string;
22	}
23	
24	interface TwilioMessageResponse {
25	  sid: string;
26	  status: string;
27	  error_code?: number;
28	  error_message?: string;
29	}
30	
31	/** Send an SMS via Twilio REST API */
32	async function sendViaTwilio(
33	  accountSid: string,
34	  authToken: string,
35	  fromNumber: string,
36	  toPhone: string,
37	  body: string
38	): Promise<{ ok: boolean; sid?: string; errorMessage?: string }> {
39	  const url = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
40	
41	  const params = new URLSearchParams();
42	  params.append("To", toPhone);
43	  params.append("From", fromNumber);
44	  params.append("Body", body);
45	
46	  const credentials = btoa(`${accountSid}:${authToken}`);
47	
48	  const res = await fetch(url, {
49	    method: "POST",
50	    headers: {
51	      "Authorization": `Basic ${credentials}`,
52	      "Content-Type": "application/x-www-form-urlencoded",
53	    },
54	    body: params.toString(),
55	  });
56	
57	  const json = (await res.json()) as TwilioMessageResponse;
58	
59	  if (!res.ok) {
60	    return {
61	      ok: false,
62	      errorMessage: json.error_message || `Twilio error (status ${res.status}, code ${json.error_code})`,
63	    };
64	  }
65	
66	  return { ok: true, sid: json.sid };
67	}
68	
69	serve(async (req) => {
70	  const corsHeaders = {
71	    "Access-Control-Allow-Origin": getCorsOrigin(req),
72	    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
73	  };
74	  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
75	
76	  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
77	  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
78	  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
79	
80	  // Verify JWT
81	  const authHeader = req.headers.get("Authorization");
82	  if (!authHeader) {
83	    return new Response(JSON.stringify({ error: "Missing authorization header" }), {
84	      status: 401,
85	      headers: { ...corsHeaders, "Content-Type": "application/json" },
86	    });
87	  }
88	
89	  const token = authHeader.replace("Bearer ", "");
90	  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
91	  if (authError || !user) {
92	    return new Response(JSON.stringify({ error: "Unauthorized" }), {
93	      status: 401,
94	      headers: { ...corsHeaders, "Content-Type": "application/json" },
95	    });
96	  }
97	
98	  try {
99	    const body = (await req.json()) as SendSmsRequest;
100	    const { resume_id, job_id, to_phone, message } = body;
101	
102	    if (!resume_id || !job_id || !to_phone || !message) {
103	      return new Response(
104	        JSON.stringify({ error: "Missing required fields: resume_id, job_id, to_phone, message" }),
105	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
106	      );
107	    }
108	
109	    if (message.length > 1600) {
110	      return new Response(
111	        JSON.stringify({ error: "Message too long. Maximum 1600 characters." }),
112	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
113	      );
114	    }
115	
116	    // Load Twilio credentials from Supabase Edge Function Secrets
117	    const accountSid = Deno.env.get("TWILIO_ACCOUNT_SID");
118	    const authToken = Deno.env.get("TWILIO_AUTH_TOKEN");
119	    const fromNumber = Deno.env.get("TWILIO_FROM_NUMBER");
120	
121	    if (!accountSid || !authToken || !fromNumber) {
122	      return new Response(
123	        JSON.stringify({
124	          error: "SMS not configured. Set TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, and TWILIO_FROM_NUMBER in Supabase Edge Function Secrets.",
125	          not_configured: true,
126	        }),
127	        { status: 503, headers: { ...corsHeaders, "Content-Type": "application/json" } }
128	      );
129	    }
130	
131	    // Send via Twilio
132	    const result = await sendViaTwilio(accountSid, authToken, fromNumber, to_phone, message);
133	
134	    const logStatus = result.ok ? "sent" : "failed";
135	
136	    // Log to sms_logs regardless of send result
137	    const { error: logError } = await supabase.from("sms_logs").insert({
138	      user_id: user.id,
139	      resume_id,
140	      job_id,
141	      to_phone,
142	      message,
143	      status: logStatus,
144	      twilio_sid: result.sid ?? null,
145	      error: result.errorMessage ?? null,
146	    });
147	
148	    if (logError) {
149	      console.error("Failed to log SMS:", logError.message);
150	      await logSystemError({
151	        function_name: "send-sms",
152	        error_type: "SMS_LOG_ERROR",
153	        severity: "warning",
154	        error_message: `Failed to log SMS: ${logError.message}`,
155	        user_id: user.id,
156	        job_id,
157	        resume_id,
158	      });
159	    }
160	
161	    if (!result.ok) {
162	      console.error("Twilio error:", result.errorMessage);
163	      await logSystemError({
164	        function_name: "send-sms",
165	        error_type: "TWILIO_SEND_ERROR",
166	        severity: "warning",
167	        error_message: `Twilio send error: ${result.errorMessage}`,
168	        user_id: user.id,
169	        job_id,
170	        resume_id,
171	      });
172	      return new Response(
173	        JSON.stringify({ error: result.errorMessage }),
174	        { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
175	      );
176	    }
177	
178	    return new Response(
179	      JSON.stringify({ success: true, twilio_sid: result.sid }),
180	      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
181	    );
182	  } catch (err: unknown) {
183	    console.error("send-sms error:", err);
184	    await logSystemError({
185	      function_name: "send-sms",
186	      error_type: "SMS_SEND_ERROR",
187	      severity: "warning",
188	      error_message: errorToMessage(err),
189	      error_stack: errorToStack(err),
190	      user_id: user.id,
191	    });
192	    return new Response(
193	      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
194	      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
195	    );
196	  }
197	});
